with valid as (select *, case when budget >= 3638000 then 'High' when budget >= 626000 then 'Medium' else 'Low' end as budget_tier from departments where dept_name is not null and location <> 'Chiang Mai'), base as (select *, ceil(budget) as budget_whole, lower(dept_name) as dept_name_lower from valid where dept_name is not null and location = 'Bangkok'), latest as (select *, row_number() over (partition by dept_name order by budget_whole desc nulls last, id asc) as row_num from base qualify row_num = 1), not_flagged as (select s.* from latest s where not exists (select 1 from employees c where c.dept_id = s.id and c.job_title <> 'Director')), with_windows as (select id, dept_name, location, budget, budget_tier, budget_whole, dept_name_lower, row_num, round(budget / sum(budget) over (partition by location, dept_name), 4) as budget_share, cume_dist() over w_part as budget_whole_cume_dist, ntile(10) over (partition by location, dept_name order by budget desc, id asc) as budget_bucket from not_flagged window w_part as (partition by location order by budget_whole desc nulls last)) select dept_name, count(*) filter (where location = 'Bangkok') as bangkok_rows, count(*) filter (where location = 'Tokyo') as tokyo_rows from with_windows group by dept_name order by tokyo_rows desc
